from flask import Flask, jsonify, request
from functools import wraps
import jwt
import datetime

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key-here'

# In-memory database (gerçek uygulamada SQL/NoSQL kullan)
users = {
    1: {"id": 1, "name": "John Doe", "email": "john@example.com"},
    2: {"id": 2, "name": "Jane Smith", "email": "jane@example.com"}
}

# Authentication decorator
def token_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')

        if not token:
            return jsonify({'message': 'Token missing'}), 401

        try:
            # "Bearer <token>" formatından token'ı çıkar
            token = token.split()[1] if ' ' in token else token
            data = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
        except:
            return jsonify({'message': 'Invalid token'}), 401

        return f(*args, **kwargs)

    return decorated

# Login endpoint
@app.route('/api/login', methods=['POST'])
def login():
    """
    Kullanıcı girişi yapar ve JWT token döner.
    """
    data = request.get_json()

    # Basit authentication (gerçek uygulamada hash kontrol et)
    if data.get('username') == 'admin' and data.get('password') == 'admin123':
        token = jwt.encode({
            'user': data['username'],
            'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=24)
        }, app.config['SECRET_KEY'])

        return jsonify({'token': token})

    return jsonify({'message': 'Invalid credentials'}), 401

# GET all users
@app.route('/api/users', methods=['GET'])
@token_required
def get_users():
    """
    Tüm kullanıcıları döner.
    Requires: Authentication token
    """
    return jsonify(list(users.values()))

# GET single user
@app.route('/api/users/<int:user_id>', methods=['GET'])
@token_required
def get_user(user_id):
    """
    Belirli bir kullanıcıyı döner.
    """
    user = users.get(user_id)

    if user:
        return jsonify(user)

    return jsonify({'message': 'User not found'}), 404

# POST create user
@app.route('/api/users', methods=['POST'])
@token_required
def create_user():
    """
    Yeni kullanıcı oluşturur.
    """
    data = request.get_json()

    # Validation
    if not data.get('name') or not data.get('email'):
        return jsonify({'message': 'Name and email required'}), 400

    new_id = max(users.keys()) + 1
    new_user = {
        'id': new_id,
        'name': data['name'],
        'email': data['email']
    }

    users[new_id] = new_user
    return jsonify(new_user), 201

# PUT update user
@app.route('/api/users/<int:user_id>', methods=['PUT'])
@token_required
def update_user(user_id):
    """
    Kullanıcı bilgilerini günceller.
    """
    if user_id not in users:
        return jsonify({'message': 'User not found'}), 404

    data = request.get_json()
    users[user_id].update(data)

    return jsonify(users[user_id])

# DELETE user
@app.route('/api/users/<int:user_id>', methods=['DELETE'])
@token_required
def delete_user(user_id):
    """
    Kullanıcıyı siler.
    """
    if user_id in users:
        del users[user_id]
        return jsonify({'message': 'User deleted'}), 200

    return jsonify({'message': 'User not found'}), 404

if __name__ == '__main__':
    app.run(debug=True)
